    concepts: [
      { id: 'acn-1', term: 'VPC Architecture', summary: 'Isolated logical networks within a cloud provider.', detail: 'Virtual Private Clouds segment cloud resources. Define CIDR ranges, subnets, route tables, and gateways. Use VPC peering, transit gateways, or private service connect for private cross-resource communication.', category: 'Networking' },
      { id: 'acn-2', term: 'Subnet Design & IPAM', summary: 'Division of VPC CIDR into usable subnets.', detail: 'IP Address Management avoids overlap. Reserve private, public, and inter-VPC ranges carefully. Use IPv6 alongside IPv4 where supported. Track allocations centrally to prevent exhaustion.', category: 'Networking' },
      { id: 'acn-3', term: 'Security Groups & NACLs', summary: 'Stateful and stateless traffic filters.', detail: 'Security groups operate at the instance layer and are stateful. Network ACLs are stateless subnet-level filters. Combine them for layered defense.', category: 'Networking' },
      { id: 'acn-4', term: 'Load Balancing', summary: 'L4 and L7 traffic distribution patterns.', detail: 'Network load balancers handle TCP/UDP at Layer 4. Application load balancers add Layer 7 routing by host, path, and header, plus TLS termination and WAF integration. Choose by latency, throughput, and feature needs.', category: 'Networking' },
      { id: 'acn-5', term: 'Private Connectivity', summary: 'Dedicated private links instead of public internet paths.', detail: 'Site-to-site VPNs encrypt over the internet. Dedicated links provide lower latency and predictable throughput. Private endpoints expose services inside your VPC without transit through the public internet.', category: 'Networking' },
      { id: 'acn-6', term: 'Cloud DNS & Traffic Management', summary: 'Hosted zones, private resolution, and routing policies.', detail: 'Use public and private hosted zones. Routing policies include weighted, latency, geo, and failover. Combine with low TTLs for cutovers and higher TTLs for stable traffic.', category: 'Networking' },
      { id: 'acn-7', term: 'Service Endpoints & PrivateLink', summary: 'Provider services accessed over private IP.', detail: 'Consume SaaS or PaaS via private endpoint interfaces in your VPC. This removes exposure to the public internet and simplifies routing and security posture.', category: 'Networking' },
      { id: 'acn-8', term: 'Traffic Inspection & Mirroring', summary: 'Duplicating packets for monitoring and forensics.', detail: 'Packet mirroring sends traffic copies to appliances for IDS/IPS, DDoS forensics, and traffic analytics. Flow logs supplement analysis with which endpoints communicate over which ports.', category: 'Networking' },
    ],
